import csv,re,json,collections
inv={r['id']:float(r['amount']) for r in csv.DictReader(open('backoffice/invoices.csv',encoding='utf-8'))}
pay=collections.defaultdict(list)
for r in csv.DictReader(open('backoffice/bank_statement_june.csv',encoding='utf-8')):
    m=re.search(r'inv(?:oice)?[-\s]?(\d{4})',r['memo'],re.I)
    if not m or 'unidentified' in r['memo'].lower(): print('skip',r['memo']);continue
    pay['INV-'+m.group(1)].append(float(r['amount']))
for k in pay:
    if k not in inv: print('unknown',k)
o={'unpaid':[],'duplicated':[],'mismatched':[]}
for i in sorted(inv):
    p=pay.get(i,[])
    if not p:o['unpaid'].append(i)
    elif len(p)>1:o['duplicated'].append(i)
    elif abs(p[0]-inv[i])>0.005:o['mismatched'].append({'id':i,'invoiced':inv[i],'paid':p[0]})
json.dump(o,open('result.json','w'),indent=1);print(o)
